from research.dialogue_question_formulation_v1 import formulate_question

def intent(kind='closed_observability',key='closed_observability:commercial'):
 return{'intent_key':key,'family':'commercial','question_type':kind,'label':'un comercio o equipamiento identificable','canonical_question':'Sin asumir que sea visible, ¿puedes observar un comercio o equipamiento identificable? Responde libremente o indica que no puedes comprobarlo.','evidence_refs':('node/1',),'grounding_kind':'positive_cartographic_existence_only','visibility_supported':False,'object_object_relation_supported':False if kind=='open_spatial' else None,'observer_heading_available':False if kind=='open_observer_relative' else None,'supported_hypothesis_ids':('h1',),'unknown_hypothesis_ids':('h2',),'utility':(2,.5,1,1,-1),'selection_reason':'supported_vs_unknown_hypotheses'}
def test_formulation_is_deterministic_auditable_and_preserves_uncertainty():
 first=formulate_question(intent(),('church',));second=formulate_question(intent(),('church',));assert first==second;assert first['generation_method']=='deterministic_controlled_variant';assert 'commercial' in first['question_id'];assert any(term in first['display_question'].casefold() for term in ('no puedes','no lo sabes','no es observable'))
def test_history_can_vary_wording_without_changing_intent():
 variants={formulate_question(intent(),(value,))['display_question'] for value in ('a','b','c','d','e')};assert len(variants)>1;assert {formulate_question(intent(),(value,))['semantic_intent'] for value in ('a','b')}=={'closed_observability'}

def test_all_families_preserve_abstention_and_audit_fields():
 fixtures=[intent(),{**intent('open_spatial','open_human_relation:church|square'),'family':'spatial:church|square','left':'una iglesia','right':'una plaza'},{**intent('open_distinctive','open_distinctive:monument'),'family':'open_distinctive:monument','label':'un monumento'},{**intent('open_qualitative_proximity','open_qualitative_proximity:park'),'family':'open_qualitative_proximity:park','label':'un parque'},{**intent('open_observer_relative','observer_relative:left'),'family':'observer_relative:left','direction':'a tu izquierda'}]
 for row in fixtures:
  result=formulate_question(row,('used',));assert any(term in result['display_question'].casefold() for term in ('no puedes','no lo sabes','no es observable'));assert result['question_id']==row['intent_key'];assert result['target_attribute']==row['family'];assert result['candidate_evidence']==row['evidence_refs'];assert result['utility']==row['utility'] and result['supported_hypothesis_ids']==row['supported_hypothesis_ids'] and result['unknown_hypothesis_ids']==row['unknown_hypothesis_ids'];assert result['grounding_kind']==row['grounding_kind'] and result['visibility_supported'] is False;assert result['object_object_relation_supported']==row.get('object_object_relation_supported') and result['observer_heading_available']==row.get('observer_heading_available');assert result['equivalence_status']=='pending_human_review'
